const item = Array.isArray(input) ? input[0]?.json || input[0] : input?.json || input;
const action = item?.action || '';
const body = item?.body || {};
const requestId = item?.requestId || ('req_' + Date.now());

const routeDomain = (act) => {
  if (act.startsWith('auth/')) return 'AUTH';
  if (act.startsWith('seller/') || act.startsWith('properties/')) return 'SELLER';
  if (act.startsWith('shortlists/') || act.startsWith('interests/') || 
