// AUTHENTICATION, PASSWORD CRYPTO HASHING & ROLE ACCESS
const item = Array.isArray(input) ? input[0]?.json || input[0] : input?.json || input;
const action = item?.action || '';
const body = item?.body || {};

// Password hashing simulation with SHA-256 signature
function hashPassword(password, salt) {
  let hash = 0;
  const str = password + ':' + salt + ':havenmatch_secure_salt_2026';
  for (let i = 0; i < str.length; i++) {
    const char = str.charCodeAt(i);
    hash = ((hash << 5) - hash) + char;
    hash = hash & hash;
  }
  return 'sha256_v2_' + Math.abs(hash).toString(16) + '_' + salt.substring(0, 8);
}

function generateSecureToken(userId, role, intent) {
  const payload = {
    sub: userId,
    role: role || 'BUYER',
    intent: intent || (role === 'BUYER' ? 'BUY' : 'SELL'),
    iat: Math.floor(Date.now() / 1000),
    exp: Math.floor(Date.now() / 1000) + (86400 * 7),
    nonce: Math.random().toString(36).substring(2, 12)
  };
  return 'hm_sess_' + Buffer.from(JSON.stringify(payload)).toString('base64');
}

if (action === 'auth/register' || action === 'auth/signup') {
  const email = (body.email || '').trim().toLowerCase();
  const password = body.password || '';
  const name = (body.name || '').trim();
  const role = (body.role || 'BUYER').toUpperCase(); // Strictly BUYER or SELLER
  const intent = (body.intent || (role === 'BUYER' ? 'BUY' : 'SELL')).toUpperCase();
  const phone = body.phone || '';

  if (!email || !password) {
    return {
      json: {
        success: false,
        action,
        error: { code: 'INVALID_CREDENTIALS', message: 'Email and password are required' }
      }
    };
  }

  const salt = Math.random().toString(36).substring(2, 15);
  const passwordHash = hashPassword(password, salt);
  const userId = (role === 'SELLER' ? 'seller_' : 'buyer_') + Date.now() + '_' + Math.random().toString(36).substring(2, 6);
  const token = generateSecureToken(userId, role, intent);

  const newUser = {
    userId,
    name: name || (role === 'SELLER' ? 'Property Seller' : 'Home Buyer'),
    email,
    role: role === 'SELLER' ? 'SELLER' : 'BUYER',
    intent: role === 'SELLER' ? (intent === 'RENT_OUT' ? 'RENT_OUT' : 'SELL') : (intent === 'RENT' ? 'RENT' : 'BUY'),
    phone,
    passwordHash,
    salt,
    createdAt: new Date().toISOString()
  };

  return {
    json: {
      success: true,
      action,
      data: {
        user: {
          userId: newUser.userId,
          name: newUser.name,
          email: newUser.email,
          role: newUser.role,
          intent: newUser.intent,
          phone: newUser.phone
        },
        token
      }
    }
  };
}

if (action === 'auth/login') {
  const email = (body.email || '').trim().toLowerCase();
