// DETERMINISTIC HARD CONSTRAINTS FILTERING ENGINE
const items = Array.isArray(input) ? input : (input?.items || [input]);
const propertiesList = items.map(i => i?.json || i).filter(p => p && (p.propertyId || p.title));
const profile = input?.buyerProfile || items[0]?.json?.buyerProfile || {};

const budgetLimit = profile.budget ? profile.budget * 1.25 : 15000000;
const reqBedrooms = profile.bedrooms || 0;
const reqIntent = (profile.intent || 'BUY').toUpperCase();

// If properties were not returned by upstream DB query, read from payload
const activeProps = propertiesList.length > 0 ? propertiesList : (profile.properties || []);

const eligibleProperties = activeProps.filter(prop => {
  // Hard Filter 1: Intent alignment (BUY / RENT)
  if (prop.intent && reqIntent) {
    const propIntent = prop.intent.toUpperCase();
    if (reqIntent === 'RENT' && propIntent === 'SELL') return false;
    if (reqIntent === 'BUY' && propIntent === 'RENT_OUT') return false;
  }

  // Hard Filter 2: Budget envelope
  const price = Number(prop.price) || 0;
  if (price > 0 && price > budgetLimit) return false;

  // Hard Filter 3: Minimum Bedroom Count
  const beds = Number(prop.bedrooms) || 0;
  if (reqBedrooms > 0 && beds > 0 && beds < (reqBedrooms - 1)) return false;

  // Hard Filter 4: Status must be active
  if (prop.status && prop.status.toLowerCase() !== 'active') return false;

  return true;
});

return {
  json: {
    buyerProfile: profile,
    eligibleProperties,
    candidateCount: eligibleProperties.length
  }
};

// WEIGHTED SOFT PREFERENCES & AMENITIES EVALUATOR
const item = Array.isArray(input) ? input[0]?.json || input[0] : input?.json || input;
