const scoredCandidates = candidates.map(prop => {
  let softScore = 0;
  const factors = [];

  // 1. Budget Fit Scoring
  const price = Number(prop.price) || profile.budget || 5000000;
  const targetBudget = profile.budget || price;
  const budgetRatio = price / targetBudget;
  let budgetScore = 100;
  if (budgetRatio <= 1.0) {
    budgetScore = 100;
    factors.push('Within exact target budget');
  } else if (budgetRatio <= 1.15) {
    budgetScore = 85;
    factors.push('Slightly above target budget (+15%)');
  } else {
