// Haversine formula calculation in KM
function haversineDistance(lat1, lon1, lat2, lon2) {
  const R = 6371;
  const dLat = (lat2 - lat1) * Math.PI / 180;
  const dLon = (lon2 - lon1) * Math.PI / 180;
  const a = Math.sin(dLat / 2) * Math.sin(dLat / 2) +
            Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) *
            Math.sin(dLon / 2) * Math.sin(dLon / 2);
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
  return R * c;
}

// Default reference coordinates for key hubs
const HUB_COORDINATES = {
  'Tidel Park': { lat: 11.0260, lng: 77.0180 },
  'Gandhipuram': { lat: 11.0168, lng: 76.9678 },
  'Saibaba Colony': { lat: 11.0238, lng: 76.9452 },
  'Saravanampatti': { lat: 11.0797, lng: 76.9996 },
  'RS Puram': { lat: 11.0085, lng: 76.9490 }
};

const scoredProperties = candidates.map(prop => {
  const propLat = Number(prop.latitude) || 11.0168;
  const propLng = Number(prop.longitude) || 76.9558;

  // Dynamic commute distance
  const targetHub = HUB_COORDINATES['Tidel Park'];
  const distanceKm = haversineDistance(propLat, propLng, targetHub.lat, targetHub.lng);
  const commuteTimeMin = Math.round(distanceKm * 2.8 + 5);

  let locationScore = Math.max(50, Math.min(100, Math.round(100 - distanceKm * 4.5)));
  const commuteScore = Math.max(40, Math.min(100, Math.round(100 - (commuteTimeMin / 45) * 50)));

  // Calculate Weighted Composite Match Score
  const w = profile.weights || { budget: 0.25, bedrooms: 0.20, location: 0.20, commute: 0.15, amenities: 0.10, vastuSiruvani: 0.10 };

  const rawScore = (
    (prop.budgetScore || 85) * (w.budget || 0.25) +
    (prop.bedScore || 90) * (w.bedrooms || 0.20) +
    locationScore * (w.location || 0.20) +
    commuteScore * (w.commute || 0.15) +
    (prop.lifestyleScore || 80) * (w.amenities || 0.10) +
    90 * (w.vastuSiruvani || 0.10)
  );

  const matchScore = Math.min(99, Math.max(65, Math.round(rawScore)));

  const reasons = [...(prop.positiveFactors || [])];
  reasons.push(`${commuteTimeMin} min drive to IT corridor / business hub (${distanceKm.toFixed(1)} km)`);

  return {
    ...prop,
    distanceKm: Number(distanceKm.toFixed(1)),
    commuteTimeMin,
    locationScore,
    commuteScore,
    matchScore,
    reasons
  };
});

